function splitList(text){ return String(text||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function buildAdr(f){
  f=f||{};
  var id=String(f.id||'0001').trim()||'0001';
  var title=String(f.title||'未命名决策').trim()||'未命名决策';
  var status=String(f.status||'提议 Proposed').trim()||'提议 Proposed';
  var date=String(f.date||'').trim()||'(待填)';
  var context=String(f.context||'').trim()||'(待补充)';
  var decision=String(f.decision||'').trim()||'(待补充)';
  var alts=splitList(f.alternatives), cons=splitList(f.consequences);
  var lines=[];
  lines.push('# ADR-'+id+'：'+title);
  lines.push('');
  lines.push('- 状态：'+status);
  lines.push('- 日期：'+date);
  lines.push('');
  lines.push('## 背景 / 问题');
  lines.push(context);
  lines.push('');
  lines.push('## 决策');
  lines.push(decision);
  lines.push('');
  lines.push('## 考虑的备选方案');
  if(alts.length) alts.forEach(function(a){lines.push('- '+a);}); else lines.push('- （待补充）');
  lines.push('');
  lines.push('## 后果');
  if(cons.length) cons.forEach(function(c){lines.push('- '+c);}); else lines.push('- （待补充）');
  return {id:id, title:title, status:status, markdown:lines.join('\n'), altCount:alts.length, consCount:cons.length};
}
var EXPORTS={splitList:splitList, buildAdr:buildAdr};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AdrForgePure = EXPORTS; }
